var n=`0447-kjotsupa`;var i=`world-0447`;var a=`IS`;var o=`northern-europe`;var s=4;var r=125;var l={en:`Kjötsúpa`,ua:`М'ясний суп по-ісландськи`};var g={en:`A traditional dish from Iceland, centered on lamb, yellow onion, potato, carrot. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ісландія. Основні складники: ягнятина, жовта цибуля, картопля, морква. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 90 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 90 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:90,i:[[`lamb`,650,`g`],[`water`,1400,`ml`],[`yellow-onion`,200,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`potato`,560,`g`],[`carrot`,280,`g`],[`turnip`,230,`g`],[`white-cabbage`,260,`g`],[`thyme`,3,`sprig`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:n,id:i,country:`IS`,region:o,servings:4,minutes:125,title:l,text:g,steps:m};export{a as country,d as default,i as id,r as minutes,o as region,s as servings,n as slug,m as steps,g as text,l as title};